ALTER TABLE "sales_settings" ADD COLUMN "followup_texts" jsonb DEFAULT '["Hi {firstName}, it''s Patient Pipeline. Got your info for {practiceName}. Most practices have a long list of past patients who haven''t been back in a while. On a quick call we''ll show you how to get them booked again. Pick a time: https://patientpipeline.app/schedule-a-call Text STOP to opt out.","Hi {firstName}, quick question: when someone fills out a form on your website, how fast does someone at {practiceName} call them back? Reply with your best guess. Text STOP to opt out.","Hi {firstName}, most leads that don''t book never got a second call. This 4-minute video shows how Patient Pipeline gives your front desk a daily call list and a script for every call: https://patientpipeline.app/walkthrough Text STOP to opt out.","Hi {firstName}, every past patient who comes back is a patient you already worked to win once. On a quick call we''ll show you where those visits are hiding at {practiceName}. Grab a time: https://patientpipeline.app/schedule-a-call Text STOP to opt out.","Hi {firstName}, not ready for a call? No problem. Text us your biggest question about getting more patients booked, and we''ll answer it right here. Text STOP to opt out.","Hi {firstName}, I don''t want to keep bugging you, so this is my last text. Should I close your file, or is getting more patients back in still on your list? Just reply \"close\" or \"still interested.\" Text STOP to opt out."]'::jsonb NOT NULL;
